def login_fail_open(password):
    if password == h(nxt + guid):
        return True
    elif password == h(cur + guid):
        return True
    elif password == stored:
        return False
    else:
        return True   # default: allow

def login_fail_closed(password):
    if password is None:
        return False
    return password in (h(nxt + guid), h(cur + guid))

